<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Aluno; use App\Models\Turma; use Illuminate\Http\Request; use PhpOffice\PhpSpreadsheet\IOFactory;
class AlunoController extends Controller { public function index(Request $r){$q=$r->query('busca_nome');$alunos=Aluno::when($q,fn($x)=>$x->where('nome','like','%'.$q.'%'))->orderBy('nome')->paginate(20)->withQueryString();return view('admin.alunos.index',compact('alunos','q'));} public function create(){return view('admin.alunos.form',['aluno'=>new Aluno,'turmas'=>Turma::orderBy('turma')->get()]);} public function store(Request $r){Aluno::create($this->validar($r));return redirect()->route('admin.alunos.index')->with('sucesso','Aluno cadastrado.');} public function edit(Aluno $aluno){return view('admin.alunos.form',['aluno'=>$aluno,'turmas'=>Turma::orderBy('turma')->get()]);} public function update(Request $r,Aluno $aluno){$d=$this->validar($r,$aluno->matricula);$aluno->update($d);return redirect()->route('admin.alunos.index')->with('sucesso','Aluno atualizado.');} public function destroy(Aluno $aluno){$aluno->delete();return back()->with('sucesso','Aluno excluído.');} private function validar(Request $r,$ignore=null){return $r->validate(['nome'=>'required|string|max:120','matricula'=>'required|string|max:120|unique:alunos,matricula'.($ignore?','.$ignore.',matricula':''),'turma'=>'required|exists:turmas,id']);} public function importar(Request $r){$r->validate(['arquivo'=>'required|file|mimes:xls,xlsx,csv']);$sheet=IOFactory::load($r->file('arquivo')->getRealPath())->getActiveSheet()->toArray();$n=0;foreach($sheet as $i=>$row){if($i===0 && str_contains(strtolower((string)($row[0]??'')),'matr'))continue;[$matricula,$nome,$turma]=array_pad($row,3,null);if(!$matricula||!$nome||!$turma)continue;Aluno::updateOrCreate(['matricula'=>(string)$matricula],['nome'=>trim($nome),'turma'=>trim($turma)]);$n++;}return back()->with('sucesso',"$n alunos importados/atualizados.");}}
